def is_2_5_smooth(num):
    if num == 1:
        return True
    d = 2
    temp = num
    while d * d <= temp:
        if temp % d == 0:
            if d != 2 and d != 5:
                return False
            while temp % d == 0:
                temp //= d
        d += 1
    if temp > 1 and temp != 2 and temp != 5:
        return False
    return True

# R(k) = 2k^3 + 4k^2 + 3k + 1
def R(k):
    return 2 * k**3 + 4 * k**2 + 3 * k + 1

# Test k from 1 to 15
k_values = range(1, 16)
results = {}

print("k | k mod 3 | k mod 7 | Constraints OK? | R(k) | 2/5 Smooth?")
print("-" * 65)

for k in k_values:
    k_mod_3 = k % 3
    k_mod_7 = k % 7

    # Check W3's derived constraints: k != 2 mod 3 AND k != 6 mod 7
    constraints_ok = (k_mod_3 != 2) and (k_mod_7 != 6)

    r_k = R(k)
    smooth = is_2_5_smooth(r_k)

    results[k] = {
        'constraints_ok': constraints_ok,
        'R_k': r_k,
        'smooth': smooth
    }

    constraint_status = "YES" if constraints_ok else "NO"

    print(f"{k:2} | {k_mod_3:7} | {k_mod_7:7} | {constraint_status:15} | {r_k:4} | {smooth}")

# Compile final list of k values meeting criteria
solutions = []
for k, data in results.items():
    if data['constraints_ok'] and data['smooth']:
        solutions.append(k)

print("\nSolutions found (k):", solutions)

def D(n):
    return n**3 + 4*n**2 + 6*n + 4

def check_condition(n):
    Dn = D(n)
    # Check if Dn is 2/5 smooth (optional, but good sanity check)
    temp_D = Dn
    while temp_D > 1:
        if temp_D % 2 == 0:
            temp_D //= 2
        elif temp_D % 5 == 0:
            temp_D //= 5
        else:
            # Found a prime factor other than 2 or 5
            return False

    # Check divisibility: Dn | 20^(n+1)
    # 20^(n+1) = (2^2 * 5)^(n+1) = 2^(2n+2) * 5^(n+1)

    # Count factors of 2 and 5 in Dn
    a = 0
    b = 0
    temp_Dn = Dn
    while temp_Dn > 0 and temp_Dn % 2 == 0:
        a += 1
        temp_Dn //= 2
    while temp_Dn > 0 and temp_Dn % 5 == 0:
        b += 1
        temp_Dn //= 5

    if temp_Dn != 1:
        # This should not happen if the 2/5 smooth check passed, but good for robustness
        return False

    # Check exponents constraints
    if a <= 2*n + 2 and b <= n + 1:
        return True
    else:
        return False

candidates = [0, 2, 6]
results = {}
for n in candidates:
    results[n] = check_condition(n)

print("Verification Results for candidates [0, 2, 6]:")
for n, success in results.items():
    print(f"n={n}: Success = {success}")

def is_2_5_smooth(n):
    if n <= 0:
        return False
    while n % 2 == 0:
        n //= 2
    while n % 5 == 0:
        n //= 5
    return n == 1

# Search parameters
K_MAX = 50

# Store results
candidates = {}

print(f"Starting search for k up to {K_MAX}...")

for k in range(1, K_MAX + 1):
    # Constraint 1: k mod 3 != 2
    if k % 3 == 2:
        continue

    # Constraint 2: k mod 7 != 6
    if k % 7 == 6:
        continue

    # Calculate R(k) = 2k^3 + 4k^2 + 3k + 1
    try:
        R_k = 2 * (k**3) + 4 * (k**2) + 3 * k + 1
    except OverflowError:
        # Should not happen for k=50, but good practice
        print(f"Error calculating R({k}): Overflow.")
        continue

    # Check for 2/5 smoothness
    if is_2_5_smooth(R_k):
        candidates[k] = R_k
        print(f"Found candidate k={k} (n={2*k}). R({k}) = {R_k}. Smooth.")

print("\n--- Search Complete ---")
print("Candidates found (k, R(k)):")
for k, R_k in sorted(candidates.items()):
    print(f"{k}: {R_k}")
print(f"Total candidates found: {len(candidates)}")
